import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App.jsx";

const style = document.createElement("style");
style.textContent = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

  /* ══ SFIGP — Style Classique Professionnel ══
     Couleurs : Blanc · Vert ISPM #1a7a4a · Gris foncé
     Aucun glow, aucun effet néon
  ══════════════════════════════════════════════ */

  :root {
    --green:       #1a7a4a;
    --green-dk:    #145c38;
    --green-lt:    #e8f5ee;
    --green-mid:   rgba(26,122,74,.15);

    --bg:          #f5f6f8;
    --bg2:         #eceef2;
    --bg3:         #e0e3e9;
    --card:        #ffffff;
    --card2:       #fafbfc;

    --ink:         #1a1d23;
    --ink2:        #4b5563;
    --ink3:        #9ca3af;
    --ink4:        #d1d5db;

    --accent:      #1a7a4a;
    --acc-lt:      #e8f5ee;
    --acc-dk:      #145c38;

    --st-present:  #16a34a;
    --st-pres-bg:  #dcfce7;
    --st-late:     #d97706;
    --st-late-bg:  #fef3c7;
    --st-absent:   #dc2626;
    --st-abs-bg:   #fee2e2;
    --st-unset:    #6b7280;
    --st-unset-bg: #f3f4f6;

    --border:      #e5e7eb;
    --border2:     #d1d5db;

    --radius:      6px;
    --radius-lg:   10px;
    --font-body:   'Inter', system-ui, sans-serif;
    --font-mono:   'JetBrains Mono', monospace;
    --shadow:      0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
    --shadow-md:   0 4px 6px rgba(0,0,0,.07), 0 2px 4px rgba(0,0,0,.05);
  }

  /* Mode sombre — noir pur, sobre */
  [data-theme="dark"] {
    --bg:          #0f0f0f;
    --bg2:         #1a1a1a;
    --bg3:         #242424;
    --card:        #181818;
    --card2:       #1f1f1f;
    --ink:         #f0f0f0;
    --ink2:        #a0a0a0;
    --ink3:        #606060;
    --ink4:        #383838;
    --border:      #2a2a2a;
    --border2:     #333333;
    --accent:      #22a05e;
    --acc-lt:      rgba(34,160,94,.12);
    --acc-dk:      #1a7a4a;
    --green:       #22a05e;
    --green-lt:    rgba(34,160,94,.12);
    --green-mid:   rgba(34,160,94,.2);
    --st-present:  #22c55e;
    --st-pres-bg:  rgba(34,197,94,.12);
    --st-late:     #f59e0b;
    --st-late-bg:  rgba(245,158,11,.12);
    --st-absent:   #f87171;
    --st-abs-bg:   rgba(248,113,113,.12);
    --st-unset:    #9ca3af;
    --st-unset-bg: rgba(156,163,175,.08);
    --shadow:      0 1px 3px rgba(0,0,0,.4);
    --shadow-md:   0 4px 8px rgba(0,0,0,.4);
  }

  *, *::before, *::after { box-sizing:border-box; margin:0; padding:0; }
  html { font-size:14px; }
  body {
    font-family: var(--font-body);
    background: var(--bg);
    color: var(--ink);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    transition: background .2s, color .2s;
  }
  ::-webkit-scrollbar { width:4px; height:4px; }
  ::-webkit-scrollbar-track { background:transparent; }
  ::-webkit-scrollbar-thumb { background:var(--border2); border-radius:4px; }
  ::-webkit-scrollbar-thumb:hover { background:var(--accent); }

  @keyframes blink    { 0%,100%{opacity:1} 50%{opacity:.3} }
  @keyframes camScan  { 0%{top:5%} 100%{top:90%} }
  @keyframes fadeUp   { from{opacity:0;transform:translateY(6px)} to{opacity:1;transform:translateY(0)} }
  @keyframes spin     { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
  @keyframes rotate360 { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }

  input, select, textarea {
    font-family: var(--font-body);
    background: var(--card);
    color: var(--ink);
    border: 1px solid var(--border2);
    border-radius: var(--radius);
    font-size: 13px;
    padding: 7px 10px;
    transition: border-color .15s, box-shadow .15s;
  }
  input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(26,122,74,.12);
  }
  input::placeholder { color: var(--ink3); }

  button {
    font-family: var(--font-body);
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    border-radius: var(--radius);
    border: none;
    padding: 7px 14px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    transition: background .15s, color .15s, border-color .15s;
    box-shadow: none;
  }
  button.btn-primary {
    background: var(--accent);
    color: #fff;
  }
  button.btn-primary:hover { background: var(--acc-dk); }
  button.btn-secondary {
    background: var(--bg2);
    color: var(--ink2);
    border: 1px solid var(--border2);
  }
  button.btn-secondary:hover { background: var(--bg3); }
  button.btn-danger {
    background: #fee2e2;
    color: #dc2626;
    border: 1px solid #fca5a5;
  }
  button.btn-danger:hover { background: #fecaca; }
`;
document.head.appendChild(style);

window._ISPM_LOGO_B64 = "data:image/png;base64,";
createRoot(document.getElementById("root")).render(
  <StrictMode><App /></StrictMode>
);
